PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS pay_group(pay_group_id TEXT PRIMARY KEY,group_name TEXT UNIQUE NOT NULL,currency TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS employee(employee_id TEXT PRIMARY KEY,pay_group_id TEXT NOT NULL REFERENCES pay_group(pay_group_id),full_name TEXT NOT NULL,tax_id TEXT UNIQUE NOT NULL,hourly_rate REAL NOT NULL CHECK(hourly_rate>=0),active INTEGER NOT NULL CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS pay_period(pay_period_id TEXT PRIMARY KEY,start_date TEXT NOT NULL,end_date TEXT NOT NULL,CHECK(start_date<=end_date));
CREATE TABLE IF NOT EXISTS time_entry(time_entry_id TEXT PRIMARY KEY,employee_id TEXT NOT NULL REFERENCES employee(employee_id),pay_period_id TEXT NOT NULL REFERENCES pay_period(pay_period_id),work_date TEXT NOT NULL,hours REAL NOT NULL CHECK(hours>=0 AND hours<=100),approved INTEGER NOT NULL CHECK(approved IN(0,1)));
CREATE TABLE IF NOT EXISTS leave_record(leave_record_id TEXT PRIMARY KEY,employee_id TEXT NOT NULL REFERENCES employee(employee_id),pay_period_id TEXT NOT NULL REFERENCES pay_period(pay_period_id),leave_days REAL NOT NULL CHECK(leave_days>=0),status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS allowance(allowance_id TEXT PRIMARY KEY,employee_id TEXT NOT NULL REFERENCES employee(employee_id),pay_period_id TEXT NOT NULL REFERENCES pay_period(pay_period_id),allowance_type TEXT NOT NULL,amount REAL NOT NULL CHECK(amount>=0));
CREATE TABLE IF NOT EXISTS deduction(deduction_id TEXT PRIMARY KEY,employee_id TEXT NOT NULL REFERENCES employee(employee_id),pay_period_id TEXT NOT NULL REFERENCES pay_period(pay_period_id),leave_record_id TEXT REFERENCES leave_record(leave_record_id),deduction_type TEXT NOT NULL,amount REAL NOT NULL CHECK(amount>=0));
CREATE TABLE IF NOT EXISTS payroll_input(payroll_input_id TEXT PRIMARY KEY,employee_id TEXT NOT NULL REFERENCES employee(employee_id),pay_period_id TEXT NOT NULL REFERENCES pay_period(pay_period_id),gross_pay REAL NOT NULL,deductions REAL NOT NULL,net_pay REAL NOT NULL,status TEXT NOT NULL,UNIQUE(employee_id,pay_period_id));
CREATE TABLE IF NOT EXISTS validation_rule(rule_id TEXT PRIMARY KEY,rule_code TEXT UNIQUE NOT NULL,description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS exception_record(exception_id TEXT PRIMARY KEY,rule_id TEXT NOT NULL REFERENCES validation_rule(rule_id),employee_id TEXT NOT NULL REFERENCES employee(employee_id),pay_period_id TEXT NOT NULL REFERENCES pay_period(pay_period_id),record_id TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','RESOLVED')),UNIQUE(rule_id,record_id));
CREATE TABLE IF NOT EXISTS approval(approval_id TEXT PRIMARY KEY,payroll_input_id TEXT NOT NULL REFERENCES payroll_input(payroll_input_id),approver_role TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN('APPROVED','REJECTED')),approved_at TEXT NOT NULL,UNIQUE(payroll_input_id));
CREATE TABLE IF NOT EXISTS payroll_export(export_id TEXT PRIMARY KEY,payroll_input_id TEXT UNIQUE NOT NULL REFERENCES payroll_input(payroll_input_id),approval_id TEXT NOT NULL REFERENCES approval(approval_id),employee_id TEXT NOT NULL REFERENCES employee(employee_id),pay_period_id TEXT NOT NULL REFERENCES pay_period(pay_period_id),net_pay REAL NOT NULL,exported_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log(audit_id INTEGER PRIMARY KEY AUTOINCREMENT,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,action TEXT NOT NULL,old_value TEXT,new_value TEXT,actor TEXT NOT NULL,event_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_time_employee_period ON time_entry(employee_id,pay_period_id);
CREATE INDEX IF NOT EXISTS ix_allowance_employee_period_type ON allowance(employee_id,pay_period_id,allowance_type);
CREATE INDEX IF NOT EXISTS ix_deduction_employee_period_type ON deduction(employee_id,pay_period_id,deduction_type,leave_record_id);
CREATE INDEX IF NOT EXISTS ix_exception_employee_period_status ON exception_record(employee_id,pay_period_id,status);
